const unique = (values) => [...new Set((values || []).map(v => String(v || '').trim().toUpperCase()).filter(Boolean))];
const compareStable = (a, b) => String(a).localeCompare(String(b), 'vi', { sensitivity: 'base', numeric: true }) || String(a).localeCompare(String(b));
const uniqueSorted = (values) => unique(values).sort(compareStable);
const merge = (...sets) => uniqueSorted(sets.flat());
