  { primary: 'CAM', details: ['cam đất','cam'] },
  { primary: 'GHI', details: ['ghi xám','xám ghi','ghi','xám'] },
  { primary: 'XANH NGỌC', details: ['xanh ngọc'] }
];
const colorContexts = (description, attrs, title) => {
  const contexts = [];
  for (const attr of attrs || []) {
    if (/(^|\s)(màu|màu sắc|color|colour)(\s|$)/i.test(lowerVi(attr.label))) contexts.push(unicodeText(attr.value));
  }
  const lines = unicodeText(description).split(/\n|(?<=[.!?;])\s+/).map(v => v.trim()).filter(Boolean);
  for (const line of lines) {
    if (/(^|\W)(màu sắc|màu chủ đạo|gam màu|tông màu|tone màu|phối màu|màu)(\W|$)/i.test(lowerVi(line))) contexts.push(line);
  }
  const titleText = unicodeText(title);
  if (/(?:\s[-–—|]\s|\()\s*(trắng|đen|kem|nâu|đỏ|hồng|xanh|vàng|tím|cam|ghi|xám)/i.test(lowerVi(titleText))) contexts.push(titleText);
  return contexts;
};
const parseColors = (description, attrs, title, override) => {
  const overrideValues = unique(override || []);
  const contexts = overrideValues.length ? overrideValues : colorContexts(description, attrs, title);
  const haystack = lowerVi(contexts.join(' | '));
  const primary = [];
  const detail = [];
  for (const definition of colorDefinitions) {
    for (const phrase of definition.details) {
      const pattern = new RegExp('(^|[^\\p{L}])' + escapeRegex(phrase) + '([^\\p{L}]|$)', 'iu');
      if (!pattern.test(haystack)) continue;
      primary.push(definition.primary);
      detail.push(phrase.toUpperCase());
      break;
    }
  }
  if (overrideValues.length && !primary.length) return { primary: overrideValues, detail: overrideValues, contexts };
  return { primary: unique(primary), detail: unique(detail), contexts };
};

