  const summary = Object.entries(ordered).map(([key, values]) => `${componentLabels[key] || key}: ${values.join(' | ')}`).join('; ');
  if (!flat.length) warnings.push('MATERIAL_NOT_FOUND');
  return { components: ordered, flat, summary, warnings };
};

